package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.regex.*;import java.io.*;
public class ReadingFoundationRelationsTest {
 private static int answer(Question q){if(q.skillId.equals("el_decimal_place")){Matcher m=Pattern.compile("([0-9]+)\\.([0-9]+)에서 (10|100|1000)분").matcher(q.prompt);assertTrue(m.find());int pos=m.group(3).length()-2;return pos<m.group(2).length()?m.group(2).charAt(pos)-'0':0;}String target=q.prompt.substring(q.prompt.indexOf("에서 ")+3,q.prompt.indexOf(q.skillId.equals("el_picture_graph")?"의 수량":"이 차지"));return (int)q.diagram.values[Arrays.asList(q.diagram.labels).indexOf(target)];}
 @Test public void publicDecimalAndGraphGivensStayIndependentOfAnswerKeys(){Generator g=new Generator(new Random(100201));for(String id:ReadingFoundationRelations.IDS){Set<String> questions=new HashSet<>();for(int i=0;i<1600;i++){Question q=g.next(id,List.of(),i%2==0);int correct=answer(q);assertEquals(""+correct,q.answers[0]);questions.add(q.prompt+(q.diagram==null?"":Arrays.toString(q.diagram.values)));String signature=q.signature();String[] answers=q.answers.clone();StudyDiagram diagram=q.diagram;HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());var frames=ReadingFoundationRelations.frames(q);assertFalse(frames.isEmpty());HelpPlan.Draft d=p.restore(null,q.id);for(int k=0;k<p.size();k++){var f=frames.get(k);assertTrue(p.step(k).accepts(f.expected()));assertFalse(p.step(k).accepts(""));if(f.options().isEmpty()){assertFalse(p.step(k).accepts(""+(Integer.parseInt(f.expected())+1)));assertFalse(f.label(),f.label().matches(".*[0-9].*"));}else for(String key:f.options().keySet())assertEquals(key.equals(f.expected()),p.step(k).accepts(key));d.entries.set(k,f.expected());d.stage++;d.entries.add("");}assertEquals(""+correct,p.enteredAnswer(d));assertEquals(signature,q.signature());assertArrayEquals(answers,q.answers);assertSame(diagram,q.diagram);q.answers=new String[]{"999"};q.expression="999+1";q.studyGuide=new StudyGuide().step("old","999 = ","","999");p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(""+correct,p.enteredAnswer(d));}assertTrue(id+" "+questions.size(),questions.size()>=100);}}
 @Test public void omittedDecimalPlacesAndMalformedPublicGivens(){Question q=new Question("el_decimal_place","12.5에서 1000분의 1의 자리 숫자는?","","0");var f=ReadingFoundationRelations.frames(q);assertEquals(2,f.size());assertEquals("소수점 뒤 세 번째 자리",f.get(0).expected());assertEquals("0",f.get(1).expected());q.prompt="12.5에서 10000분의 1의 자리 숫자는?";assertTrue(ReadingFoundationRelations.frames(q).isEmpty());Generator g=new Generator(new Random(100202));for(String id:List.of("el_picture_graph","el_strip_graph","el_circle_graph")){q=g.next(id,List.of(),false);q.diagram.values[0]=Double.NaN;assertTrue(ReadingFoundationRelations.frames(q).isEmpty());q=g.next(id,List.of(),false);q.diagram.labels[0]="wrong";assertTrue(ReadingFoundationRelations.frames(q).isEmpty());q=g.next(id,List.of(),false);q.diagram.type="wrong";assertTrue(ReadingFoundationRelations.frames(q).isEmpty());}}
 @Test public void oldDraftResetsAndCheckedPartialSurvivesSerialization()throws Exception{for(String id:ReadingFoundationRelations.IDS){Question q=new Generator(new Random(100203)).next(id,List.of(),false);HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.stage=1;old.entries.add("999");assertEquals(0,p.restore(old,q.id).stage);HelpPlan.Draft d=p.restore(null,q.id);d.entries.set(0,ReadingFoundationRelations.frames(q).get(0).expected());d.stage=1;d.entries.add("");ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(d);HelpPlan.Draft loaded=(HelpPlan.Draft)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertEquals(1,p.restore(loaded,q.id).stage);assertEquals(d.entries.get(0),p.restore(loaded,q.id).entries.get(0));}}
}
